 Ext._define('rh.gratifications_manager.diligence.Grid', {
    extend: 'core.RestfulGrid',

    restWindow: 'rh.gratifications_manager.diligence.Window',

    configOrderToolBar: [
        'add',
        '-',
        'edit',
        'search',
        'download'
    ],

    hideActions: ['edit', 'remove', 'copy'],

    //hideItemsToolbar: ['download'],

    doDownload: function() {
        var filtro_conferencia = 'todos';
        this._toolbar.items.items.forEach(function(item){
            if(item.text == 'Filtrar Conferência'){
                item.menu.items.items.forEach(function(item_menu){
                    if(item_menu.checked){ filtro_conferencia = item_menu.id; }
                });
            }
        });

        var config = {
            filter: Ext.encode(this.getFilter()),
            keyword: this.getKeywordField().getValue(),
            start: 0,
            limit: this.getStore().getTotalCount(),
            filtro_conferencia: filtro_conferencia,
            format: 'text/csv'
        };

        var rest = this.factoryRestful();
        var url = rest.getRoute('export').url + '?' + Ext.urlEncode(config);

        window.open(url, '_self');
    },

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: 'Chave', dataIndex: 'pk', width: 60, hidden: true},
                    {header: 'Descrição', dataIndex: 'unicode', id: 'autoExpandColumn', hidden: true},
                    {header: '', dataIndex: 'icons_diligence', sortable: true, width: 50, menuDisabled: true, renderer: toolkit.util.formatStatus },
                    {header: 'Comarca', dataIndex: 'comarca_unicode', width: 150},
                    {header: '', dataIndex: 'icons_titular', sortable: true, width: 50, menuDisabled: true, renderer: toolkit.util.formatStatus },
                    {header: 'Titular', dataIndex: 'servidor_unicode', width: 250},
                    {header: 'Qtd Dias Consolidado', dataIndex: 'qtd_dias_consolidado_titular', width: 120},
                    {header: 'Qtd Dias Deferido', dataIndex: 'qtd_dias_deferido_titular', width: 110},
                    {header: '', dataIndex: 'icons_substituto', sortable: true, width: 50, menuDisabled: true, renderer: toolkit.util.formatStatus },
                    {header: 'Substituto', dataIndex: 'substituto_unicode', width: 250},
                    {header: 'Qtd Dias Consolidado', dataIndex: 'qtd_dias_consolidado_substituto', width: 120},
                    {header: 'Qtd Dias Deferido', dataIndex: 'qtd_dias_deferido_substituto', width: 110},
                    {header: 'Data Início', dataIndex: 'data_inicio', width: 70, renderer: Ext.util.Format.dateRenderer('d/m/Y')},
                    {header: 'Data Fim', dataIndex: 'data_fim', width: 70, renderer: Ext.util.Format.dateRenderer('d/m/Y')},
                    {header: 'Evento Número', dataIndex: 'evento_numero', hidden: true}
                ]
            );

        return this._columnModel;
    },

    getToolbar: function(cfg) {
        if(!this._toolbar) {
            var itensTollBar = this.getConfigItemsToolbar(cfg);

            itensTollBar.splice(3, 0, '-');
            itensTollBar.splice(4, 0, '->');
            itensTollBar.splice(5, 0, this.btnAcaoCalcular());
            itensTollBar.splice(6, 0, '-');
            itensTollBar.splice(7, 0, 'Ano: ');
            itensTollBar.splice(8, 0, this.comboAno());
            itensTollBar.splice(9, 0, '-');
            itensTollBar.splice(10, 0, 'Mês: ');
            itensTollBar.splice(11, 0, this.comboMes());
            itensTollBar.splice(12, 0, '-');
            
            var menuFiltroConferencia = this.menuFiltro();
            itensTollBar.splice(
                15,
                0,
                {
                    text: 'Filtrar',
                    iconCls: 'icon-patrimonio icon-pat-filter',
                    menu: menuFiltroConferencia,
                }
            )

            this._toolbar = Ext._create('Ext.Toolbar', {
                style: cfg.toolbarStyle,
                items: itensTollBar,
            });

            if((this.toolbarHideLabel || cfg.toolbarHideLabel))
                this._toolbar.items.each(
                    function(item) {
                        item.tooltip = (item.tooltip || item.text);

                        if(item.text && core.nullValue(item.hideLabel, true))
                            item.text = null;
                    }
                );
        }

        return this._toolbar;
    },

    menuFiltroItem: function(id, texto, checked){
        return {
            id: id,
            text: texto,
            checked: checked,
            scope: this,
            hideOnClick: false,
            handler: function(chk) { this.filtrarItens(chk, id) },
        }
    },

    menuFiltro: function(){
        var _menuFiltroStatus = [
            this.menuFiltroItem('todos', 'Todos', true),
            this.menuFiltroItem('nao_calculado', 'Não Calculado', false),
            this.menuFiltroItem('avaliar', 'Em Avaliação', false),
            this.menuFiltroItem('deferido', 'Deferido', false),
            this.menuFiltroItem('indeferido', 'Indeferido', false),
        ];

        return _menuFiltroStatus;
    },

    filtrarItens: function(chk, opcao){
        var filtro = []
        if(!chk.checked == true){
            this._toolbar.activeMenuBtn.menu.items.items.forEach(function(item){
                if(item.id != opcao && item.checked == true){
                    item.setChecked(false);
                }else{
                    filtro.push(opcao);
                }
            });
        }else if(!chk.checked == false && opcao == 'todos'){
            filtro.push(opcao);

            if(opcao == 'todos'){
                this._toolbar.activeMenuBtn.menu.items.items.forEach(function(item){
                    if(item.id == 'todos'){
                        item.setChecked(true);
                    }else if(item.id != opcao){
                        item.setChecked(false);
                    }
                });
            }
        }

        var ano = 0;
        var mes = 0;
        this._toolbar.items.items.forEach(function(item, i){
            if(item.emptyText == 'Ano para filtro'){ ano = item.getValue(); }
            if(item.emptyText == 'Mês para filtro'){ mes = item.getValue(); }
        });

        this.getStore().baseParams['periodo_ano'] = ano;
        this.getStore().baseParams['periodo_mes'] = mes;
        this.getStore().baseParams['filtro'] = [...new Set(filtro)]
        
        if(this.getStore().lastOptions.params){
            delete this.getStore().lastOptions.params.start;
            delete this.getStore().lastOptions.params.limit;
        }
        
        this.getStore().load();
    },

    btnAcaoCalcular: function(){
        return {
            text: 'Calcular Todos',
            iconCls: 'icon-16px icon-core icon-core-run',
            scope: this,
            handler: function(){ this.calcularTodosDiligencia() },
        }
    },

    calcularTodosDiligencia: function(){
        var msg = 'Tem certeza que deseja calcular todos os registros do período selecionado? ';
        msg += 'Os registros Deferidos e Indeferidos serão ignorados.';

        var periodo_ano = 0;
        var periodo_mes = 0;
        this._toolbar.items.items.forEach(function(item, i){
            if(item.emptyText == 'Ano para filtro'){ periodo_ano = item.getValue(); }
            if(item.emptyText == 'Mês para filtro'){ periodo_mes = item.getValue(); }
        });

        var params = {
            'periodo_ano': periodo_ano,
            'periodo_mes': periodo_mes,
        }

        Ext.Msg.show({
            msg: msg,
            icon: Ext.Msg.QUESTION,
            buttons: Ext.Msg.YESNO,
            scope: this,
            fn: function (b) {
                if (b == 'no') return;

                params = params;
                this._realizarReq(params, 'GMDiligenceMoveRestful', 'calcular_todos_diligencia');
            }
        });
    },

    comboAno: function(){
        const timeElapsed = Date.now();
        var hoje = new Date(timeElapsed);

        return {
            xtype: 'combo',
            store: new Ext.data.JsonStore({
                proxy: new Ext.data.HttpProxy({
                    url: toolkit.util.Normalize.controller_action('GFPControlador', 'anos_folha', ['only']),
                    disableCaching: true,
                    method: 'GET'
                }),
                root: 'root',
                fields: ['pk', 'description']
            }),
            displayField: 'description',
            valueFeild: 'pk',
            emptyText: 'Ano para filtro',
            width: 140,
            triggerAction: 'all',
            value: hoje.getFullYear(),
            listeners: {
                scope: this,
                select: function (combo, record) {
                    var ano = record.json.pk;
                    
                    var mes = 0;
                    this._toolbar.items.items.forEach(function(item, i){
                        if(item.emptyText == 'Mês para filtro'){ mes = item.getValue(); }
                    });

                    this.filtrarAnoMes(ano, mes);
                }
            }
        }
    },

    comboMes: function(){
        const timeElapsed = Date.now();
        var hoje = new Date(timeElapsed);

        return {
            xtype: 'combo',
            store: [
                [1, 'JANEIRO'],
                [2, 'FEVEREIRO'],
                [3, 'MARÇO'],
                [4, 'ABRIL'],
                [5, 'MAIO'],
                [6, 'JUNHO'],
                [7, 'JULHO'],
                [8, 'AGOSTO'],
                [9, 'SETEMBRO'],
                [10, 'OUTUBRO'],
                [11, 'NOVEMBRO'],
                [12, 'DEZEMBRO'],
            ],
            emptyText: 'Mês para filtro',
            width: 140,
            triggerAction: 'all',
            value: hoje.getMonth() + 1,
            listeners: {
                scope: this,
                select: function (combo, record) {
                    var mes = record.json[0]

                    var ano = 0;
                    this._toolbar.items.items.forEach(function(item, i){
                        if(item.emptyText == 'Ano para filtro'){ ano = item.getValue(); }
                    });

                    this.filtrarAnoMes(ano, mes);
                }
            },
        }
    },

    filtrarAnoMes: function (ano='', mes='') {
        this.getStore().baseParams['filtro_conferencia'] = 'todos';

        if((ano === 0 || ano === 'TODOS') && mes === 0){
            this.removeFilterProperty('data_inicio__lte', 1, false);
            this.removeFilterProperty('data_fim__gte', 2, false);
            this.removeFilterProperty('data_fim__isnull', 2, true);
        }else{
            const timeElapsed = Date.now();
            hoje = new Date(timeElapsed);

            if(ano === '' && mes === ''){
                ano_filtro = hoje.getFullYear();
                mes = hoje.getMonth();
                
                var d_inicio = new Date(ano_filtro, mes).toISOString().substring(0, 10);
                var d_fim = new Date(ano_filtro, mes+1);
            }else if((ano === 0 || ano === 'TODOS') && mes != ''){
                this._toolbar.items.items.forEach(function(item, i){
                    if(item.emptyText == 'Ano para filtro'){
                        ano_filtro = item.initialConfig.store.data.items.slice(-1)[0].data.pk;
                    }
                });

                var d_inicio = new Date(ano_filtro, 0).toISOString().substring(0, 10);
                var d_fim = new Date(hoje.getFullYear(), mes);
            }else{
                if(mes == 0){
                    var d_inicio = new Date(ano, 1).toISOString().substring(0, 10);
                    var d_fim = new Date(ano, 12);
                }else{
                    var d_inicio = new Date(ano, mes-1).toISOString().substring(0, 10);
                    var d_fim = new Date(ano, mes);
                }
            }
            d_fim.setDate(d_fim.getDate() - 1);
            d_fim = d_fim.toISOString().substring(0, 10);

            this.setFilterProperty('data_inicio__lte', d_fim, 1, false);
            this.setFilterProperty('data_fim__gte', d_inicio, 2, false);
            this.setFilterProperty('data_fim__isnull', true, 2, true);
        }

        if(ano === 0 || ano === 'TODOS' || mes === 0){
            this._toolbar.items.items.forEach(function(item){
                if(item.text == 'Filtrar Conferência'){
                    item.menu.items.items.forEach(function(item_menu){
                        if(item_menu.id == 'todos'){
                            item_menu.setChecked(true);
                        }else{
                            item_menu.setChecked(false);
                        }
                        item_menu.setDisabled(true);
                    });
                }
            });
        }
        else{
            this._toolbar.items.items.forEach(function(item){
                if(item.text == 'Filtrar Conferência'){
                    item.menu.items.items.forEach(function(item_menu){
                        item_menu.setDisabled(false);
                        if(item_menu.id == 'todos'){
                            item_menu.setChecked(true);
                        }else{
                            item_menu.setChecked(false);
                        }
                    });
                }
            });
        }

    },

    _realizarReq: function(params, nome_classe, nome_metodo){
        Ext.Ajax.request({
            url: toolkit.util.Normalize.controller_action(nome_classe,nome_metodo),
            params: params,
            success: function(request) {
                var obj = Ext.decode(request.responseText);
                var icon = obj.success == true ? Ext.Msg.INFO : Ext.Msg.ERROR;
                Ext.Msg.show({
                    width:"400px",
                    title: this.title,
                    icon: icon,
                    buttons: Ext.Msg.OK,
                    msg: obj.message
                });
                if(obj.success == true){ this.getStore().reload(); }
            },
            failure: function() {
                Ext.Msg.show({
                    title: this.title,
                    icon: Ext.Msg.ERROR,
                    buttons: Ext.Msg.OK,
                    msg: 'Recurso indisponivel no momento, tente novamente mais tarde.'
                });
            },
            scope: this
        });
    },

    calcularDiligencia: function(diligencia_data){
        var calcular = false;
        var mensagem = '';
        if(diligencia_data.status_diligencia == 'DEFER'){
            mensagem = 'O registro selecionado já está DEFERIDO!';
        }else if(diligencia_data.status_diligencia == 'INDEFER'){
            mensagem = 'O registro selecionado está INDEFERIDO!';
        }else{
            calcular = true;
            var msg = 'Tem certeza que deseja calcular o registro selecionado?';

            var params = {
                'diligencia_id': diligencia_data.pk,
                'periodo_ano': diligencia_data.periodo_ano,
                'periodo_mes': diligencia_data.periodo_mes,
            }
        }

        if(calcular == true){
            Ext.Msg.show({
                msg: msg,
                icon: Ext.Msg.QUESTION,
                buttons: Ext.Msg.YESNO,
                scope: this,
                fn: function (b) {
                    if (b == 'no') return;

                    params = params;
                    this._realizarReq(params, 'GMDiligenceMoveRestful', 'calcular_diligencia');
                }
            });
        }else{
            Ext.Msg.show({
                title: this.title,
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: mensagem,
            });
        }
    },

    deferirDiligencia: function(diligencia_data){
        if(diligencia_data.status_grat_aux_coord == 'INDEFER'){
            var msg = 'O registro selecionado está INDEFERIDO, tem certeza que deseja deferir?';
        }else{
            var msg = 'Tem certeza que deseja deferir o registro selecionado?';
        }

        var params = {
            'diligencia_id': diligencia_data.pk,
            'periodo_ano': diligencia_data.periodo_ano,
            'periodo_mes': diligencia_data.periodo_mes,
        }

        Ext.Msg.show({
            msg: msg,
            icon: Ext.Msg.QUESTION,
            buttons: Ext.Msg.YESNO,
            scope: this,
            fn: function (b) {
                if (b == 'no') return;

                params = params;
                this._realizarReq(params, 'GMDiligenceMoveRestful', 'deferir_diligencia');
            }
        });
    },

    indeferirDiligencia: function(diligencia_data){
        var params = {
            'diligencia_id': diligencia_data.pk,
            'periodo_ano': diligencia_data.periodo_ano,
            'periodo_mes': diligencia_data.periodo_mes,
        }

        Ext.Msg.show({
            msg: 'Tem certeza que deseja infdeferir o registro selecionado?',
            icon: Ext.Msg.QUESTION,
            buttons: Ext.Msg.YESNO,
            scope: this,
            fn: function (b) {
                if (b == 'no') return;

                params = params;
                this._realizarReq(params, 'GMDiligenceMoveRestful', 'indeferir_diligencia');
            }
        });
    },

    getConfigCustomActions: function(){
        return [
            {
                iconCls: 'icon-16px icon-core icon-core-run',
                tooltip: 'Calcular',
                scope: this,
                handler: function(action, index){ this.calcularDiligencia(action._store.getAt(index).data); },
            },
            {
                iconCls: 'icon-16px icon-fopag icon-compile',
                tooltip: 'Deferir',
                scope: this,
                handler: function(action, index){ this.deferirDiligencia(action._store.getAt(index).data); },
            },
            {
                iconCls: 'icon-16px icon-core icon-core-delete',
                tooltip: 'Indeferir',
                scope: this,
                handler: function(action, index){ this.indeferirDiligencia(action._store.getAt(index).data); },
            },
        ];
    },

});

